import ast,hashlib,json
from pathlib import Path
r=json.load(open('/tmp/runtime_contract.json'))
p=json.loads(Path('proposal.json').read_text())
def check_schema(value,schema,path='study'):
 kind=schema.get('type')
 types={'object':dict,'array':list,'string':str,'boolean':bool}
 if kind in types: assert isinstance(value,types[kind]),(path,kind)
 if 'const' in schema: assert value==schema['const'],path
 if 'enum' in schema: assert value in schema['enum'],path
 if kind=='object':
  assert set(schema.get('required',[]))<=set(value),(path,'missing required')
  if schema.get('additionalProperties') is False: assert set(value)<=set(schema.get('properties',{})),(path,'extra property')
  for key,val in value.items():
   if key in schema.get('properties',{}):check_schema(val,schema['properties'][key],path+'.'+key)
 if kind=='array':
  assert len(value)>=schema.get('minItems',0),path
  for i,val in enumerate(value):check_schema(val,schema['items'],path+f'[{i}]')
 if kind=='string':assert len(value)>=schema.get('minLength',0),path
check_schema(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert set(p['study']['evidence_refs']) <= set(r['context']['allowed_observation_ids'])
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
base=ast.parse(Path('/tmp/incumbent_candidate.py').read_text())
base_model=next(n for n in base.body if isinstance(n,ast.ClassDef) and n.name=='Model')
base_methods={n.name:n for n in base_model.body if isinstance(n,ast.FunctionDef)}
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
for v in p['variants']:
 filename=v['file'];assert Path(filename).name==filename and filename.endswith('.py')
 source=Path(filename).read_text();compile(source,filename,'exec');tree=ast.parse(source)
 for node in ast.walk(tree):
  if isinstance(node,ast.Import): assert all(x.name.split('.')[0] in allowed for x in node.names)
  if isinstance(node,ast.ImportFrom): assert node.module.split('.')[0] in allowed
 config=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert all(config[k]==val for k,val in v['config'].items())
 model=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 methods={n.name:n for n in model.body if isinstance(n,ast.FunctionDef)}
 for name in ['_represent','_pool']:
  assert ast.dump(methods[name],include_attributes=False)==ast.dump(base_methods[name],include_attributes=False),(filename,name)
 init=methods['__init__'];defaults=dict(zip([a.arg for a in init.args.args][-len(init.args.defaults):],init.args.defaults))
 for k,val in v['config'].items():assert ast.literal_eval(defaults[k])==val
 assert source.index('self.reset_parameters()')<source.index('with torch.random.fork_rng')<source.index('self.donor_projections =')
 assert source.count('self.reset_parameters()')==1
 assert 'nn.init.zeros_(layer.weight)' in source and 'nn.init.zeros_(layer.bias)' in source
 assert not any(isinstance(n,ast.FunctionDef) and n.name=='training_loss' for n in ast.walk(tree))
 assert v['role'] in ['candidate','control']
 print(filename,'syntax/config/import/core-method checks PASS','sha256',hashlib.sha256(source.encode()).hexdigest())
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
assert hashlib.sha256(Path('/tmp/incumbent_candidate.py').read_bytes()).hexdigest()=='bc61216cd039fabbf59c4c5e36ca7f89697ce1b428be1ea7f62346931584bb87'
assert {v['config']['peer_transfer'] for v in p['variants']}=={True,False}
assert len({(v['config']['peer_transfer'],v['config']['detach_donors']) for v in p['variants']})==4
for a in p['knowledge_assessments']:
 assert set(a)=={'knowledge_id','decision','rationale','transformed_mechanism','variant_names','nearest_work_difference','falsifier'}
 assert a['decision'] in ['used','considered','rejected','unresolved']
 assert set(a['variant_names'])<=set(v['name'] for v in p['variants'])
print('Prospective study schema, evidence IDs, full factorial, baseline/incumbent source hashes, knowledge assessments: PASS')
print('No torch or model execution performed. Runtime forward/backward and performance remain unverified.')
PY"

